const prev = $('Fetch Asset & License Data').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    highRiskCount: 1,
    expiringWarranties: ["Kiểm tra thiết bị LAP-042"],
    licenseOptimization: "Cần rà soát bản quyền phần mềm",
    recommendations: ["Tối ưu hóa chi phí IT"],
    reportSummary: "Báo cáo tài sản định kỳ"
  };
}

return {
  auditDate: prev.auditDate,
  highRiskCount: parsed.highRiskCount || 0,
  expiringWarranties: parsed.expiringWarranties || [],
  licenseOptimization: parsed.licenseOptimization || '',
  recommendations: parsed.recommendations || [],
  reportSummary: parsed.reportSummary || ''
};

